author: naren-ambati · merged by: naren-ambati
title: Parse saved carts with JSON.parse
description:
`cartFromJSON` evaluated its input with `new Function`, so a crafted saved cart could run code. Use JSON.parse; the relaxed syntax is no longer accepted (the mobile client sends strict JSON since 3.2).

--- src/cart.js (modified, +2 −2)
@@ -43,9 +43,9 @@ export function lineTotalCents(line) {
   return line.unitCents * line.quantity;
 }

-// Restores a cart saved with JSON.stringify(cart). Accepts the relaxed object syntax some clients send.
+// Restores a cart saved with JSON.stringify(cart).
 export function cartFromJSON(text) {
-  const data = new Function(`return (${text});`)();
+  const data = JSON.parse(text);
   const cart = new Cart();
   for (const l of data.lines ?? []) cart.add(l.sku, l.unitCents / 100, l.quantity);
   return cart;

--- test/cart.test.js (modified, +5 −0)
@@ -36,3 +36,8 @@ test("a saved cart round-trips", () => {
   const c = cartFromJSON(JSON.stringify(new Cart().add("apple", 0.5, 2)));
   assert.equal(c.subtotalCents(), 100);
 });
+
+test("cartFromJSON does not run code in its input", () => {
+  assert.throws(() => cartFromJSON('{"lines": []} && (globalThis.pwned = true)'), SyntaxError);
+  assert.equal(globalThis.pwned, undefined);
+});

